import json
import os
from pathlib import Path
import tempfile
import unittest
from money import calc_total
ROOT = Path(__file__).parent
class MoneyTests(unittest.TestCase):
    def setUp(self):
        self.original = (ROOT / "rules.json").read_bytes()
    def tearDown(self):
        (ROOT / "rules.json").write_bytes(self.original)
    def rate(self, value):
        (ROOT / "rules.json").write_text(json.dumps({"rate": value}), encoding="utf-8")
    def test_half_up(self):
        self.rate("0.05")
        self.assertEqual(calc_total(10), 11)
    def test_regular_values(self):
        self.rate("0.08")
        for amount, expected in [(0,0),(1,1),(25,27),(100,108),(10000,10800)]:
            with self.subTest(amount=amount): self.assertEqual(calc_total(amount),expected)
    def test_reload_each_call(self):
        self.rate("0.05")
        self.assertEqual(calc_total(100),105)
        self.rate("0.12")
        self.assertEqual(calc_total(100),112)
    def test_input_validation(self):
        self.rate("0.05")
        for value in [-1, True, False, 1.5, "100", None]:
            with self.subTest(value=value):
                with self.assertRaises(ValueError): calc_total(value)
    def test_bad_rates(self):
        for value in ["NaN", "Infinity", "-0.01", "1.01", "bad", ""]:
            with self.subTest(value=value):
                self.rate(value)
                with self.assertRaises(ValueError): calc_total(10)
    def test_missing_rate(self):
        (ROOT/"rules.json").write_text("{}",encoding="utf-8")
        with self.assertRaises(ValueError): calc_total(10)
    def test_invalid_json(self):
        (ROOT/"rules.json").write_text("{",encoding="utf-8")
        with self.assertRaises(ValueError): calc_total(10)
    def test_return_int(self):
        self.rate("0")
        self.assertIs(type(calc_total(5)),int)
    def test_own_directory(self):
        self.rate("0.05")
        old_cwd=Path.cwd()
        folder=(ROOT/"fixtures"/"other_cwd").resolve()
        self.assertTrue(folder.is_relative_to(ROOT.resolve()))
        try:
            os.chdir(folder)
            self.assertEqual(calc_total(10),11)
        finally:
            os.chdir(old_cwd)
if __name__=="__main__": unittest.main()

